_BINARY_FUNCTIONS: dict[object, dict[str, str]] = {}


def _function_index(ctx) -> dict[str, str]:
    """Index sibling code by its exact harness name once per binary."""
    key = ctx.binary_key
    cached = _BINARY_FUNCTIONS.get(key)
    if cached is not None:
        return cached
    index = {}
    try:
        for harness_name, sibling in ctx.siblings.items():
            index[harness_name] = sibling
    except Exception:
        pass
    _BINARY_FUNCTIONS[key] = index
    return index


def _signature(code: str, name: str) -> str | None:
    """Return IDA's definition header as an extern declaration."""
    brace = code.find("{")
    if brace < 0:
        return None
    head = code[:brace].strip()
    head = re.sub(r"/\*.*?\*/|//[^\n]*", "", head, flags=re.S).strip()
    match = re.search(r"^(.*?)\b" + re.escape(name) + r"\s*\(", head, re.S)
    if not match:
        return None
    # IDA's parameter recovery is not consistent across optimized call sites.
    # Keep its valuable return type but use an old-style parameter list, which
    # permits the arguments present in the caller without changing their ABI.
    result_type = match.group(1).strip()
    if re.search(r"\bvoid\s*$", result_type) or "(" in result_type or ")" in result_type:
        return None
    return "extern " + result_type + " " + name + "();"


