def _known_decls(code: str, target_name: str) -> list[str]:
    out = []
    for name, result in _KNOWN_RETURNS.items():
        is_definition = re.search(
            r"^\s*[^;{}]*\b" + re.escape(name) + r"\s*\([^;{}]*\)\s*\{", code)
        if (name != target_name and not is_definition and
                re.search(r"\b" + re.escape(name) + r"\s*\(", code)):
            out.append(_EXACT_DECLS.get(name, f"extern {result} {name}();"))
    return out


def _intrinsic_decls(code: str) -> list[str]:
    """Give Intel-style helpers a vector result without importing headers."""
    out = []
    for name in sorted(set(re.findall(r"\b(_mm(?:256)?_[A-Za-z0-9_]+)\s*\(", code))):
        if re.search(r"(?:store|stream)_", name):
            result = "void"
        elif re.search(r"(?:extract|movemask|cvtsi128_si|comi|test)", name):
            result = "long long"
        elif name.startswith("_mm256_"):
            result = "__m256i"
        elif re.search(r"(?:_ps|_ss)$", name):
            result = "__m128"
        elif re.search(r"(?:_pd|_sd)$", name):
            result = "__m128d"
        else:
            result = "__m128i"
        out.append(f"extern {result} {name}();")
    return out


def _pointer_call_decls(code: str, ctx) -> list[str]:
    """Recover pointer results when IDA immediately dereferences a call."""
    try:
        sibling_names = set(_function_index(ctx))
    except Exception:
        sibling_names = set()
    out = []
    # No whitespace after '*' distinguishes IDA's unary dereference spelling
    # from a multiplication whose right operand is a call.
    for name in sorted(set(re.findall(r"\*([A-Za-z_]\w*)\s*\(", code))):
        defined = re.search(
            r"^\s*[^;{}]*\b" + re.escape(name) + r"\s*\([^;{}]*\)\s*\{", code)
        if not defined and name in sibling_names:
            defined = True
        if not defined:
            try:
                # A few sibling-map keys retain a decoration which the C
                # definition lacks.  This slower fallback is limited to the
                # uncommon immediately-dereferenced call pattern.
                defined = any(re.search(
                    r"\b" + re.escape(name) + r"\s*\(",
                    sibling.split("{", 1)[0])
                    for sibling in ctx.siblings.values())
            except Exception:
                pass
        if (not defined and name not in sibling_names and
                name not in _KNOWN_RETURNS and name not in _C_WORDS):
            out.append(f"extern unsigned char *{name}();")
    # A call result immediately used as an array is likewise necessarily a
    # pointer.  Keep the old-style parameters while preserving pointer width.
    for name in sorted(set(re.findall(
            r"\b([A-Za-z_]\w*)\s*\([^();\n]*\)\s*\[", code))):
        if (name not in sibling_names and name not in _KNOWN_RETURNS and
                name not in _C_WORDS and
                not re.search(r"\(\s*\*\s*" + re.escape(name), code)):
            out.append(f"extern unsigned char *{name}();")
    return out


def _sibling_decls(code: str, ctx) -> list[str]:
    out = []
    try:
        index = _function_index(ctx)
        target_head = code.split("{", 1)[0]
        called = set(re.findall(r"(?<![\w])([A-Za-z_]\w*)\s*\(", code))
        for name in called:
            if name == ctx.func_name:
                continue
            if re.search(r"\b" + re.escape(name) + r"\s*\(", target_head):
                continue
            if name in _KNOWN_RETURNS:
                continue
            sibling_code = index.get(name)
            if sibling_code is None:
                continue
            sig = _signature(sibling_code, name)
            if sig:
                out.append(sig)
    except Exception:
        pass
    return out


def _assigned_callee_decls(code: str, ctx) -> list[str]:
    """Declare IDA globals which are both assigned and invoked as callbacks."""
    out = []
    called = set(re.findall(r"\b([A-Za-z_]\w*)\s*\(", code))
    assigned = set(re.findall(
        r"\b([A-Za-z_]\w*)\s*(?:\+\+|--|[+\-*/&|^]?=(?!=))", code))
    try:
        sibling_names = set(_function_index(ctx))
    except Exception:
        sibling_names = set()
    for name in sorted(called & assigned):
        if (name == ctx.func_name or name in _KNOWN_RETURNS or
                name in sibling_names or name in _C_WORDS):
            continue
        if re.search(r"\(\s*\*\s*" + re.escape(name) + r"\s*\)", code):
            continue
        out.append(f"extern long long (*{name})();")
    return out


def _ida_global_decls(code: str) -> list[str]:
    """Declare IDA auto-named data objects at their encoded widths."""
    kinds = {
        "byte": "unsigned char", "word": "unsigned short",
        "dword": "unsigned int", "qword": "unsigned long long",
        "xmmword": "_OWORD", "ymmword": "__m256i",
        "flt": "float", "dbl": "double",
    }
    out = []
    seen = set()
    # A recovered 16-byte time object is often copied through an SSE load.
    # Track its aggregate type through plain assignments before choosing the
    # otherwise conservative scalar type for `stru_` objects.
    aggregate_types = {}
    for name, stype in re.findall(
            r"\b([A-Za-z_]\w*)\s*=\s*\(\{[^\n]*\bstruct\s+"
            r"(timespec|timeval)\b[^\n]*", code):
        aggregate_types[name] = stype
    for _ in range(3):
        for lhs, rhs in re.findall(
                r"\b([A-Za-z_]\w*)\s*=\s*([A-Za-z_]\w*)\s*;", code):
            if rhs in aggregate_types:
                aggregate_types[lhs] = aggregate_types[rhs]
    for prefix, ctype in kinds.items():
        for name in re.findall(r"\b" + prefix + r"_[0-9A-Fa-f]+\b", code):
            if name not in seen:
                if re.search(r"\b" + re.escape(name) +
                             r"\s*\[[^]\n]+\]\s*\(", code):
                    out.append(f"extern long long (*{name}[])();")
                elif re.search(r"\b" + re.escape(name) + r"\s*\(", code):
                    out.append(f"extern long long (*{name})();")
                elif (re.search(r"\b" + re.escape(name) + r"\s*\[", code) or
                      re.search(r"\*" + re.escape(name) + r"\b", code)):
                    out.append(f"extern {ctype} *{name};")
                else:
                    out.append(f"extern {ctype} {name};")
                seen.add(name)
    for prefix, ctype in (("unk", "unsigned char"), ("asc", "char"),
                          ("stru", "unsigned char")):
        for name in re.findall(r"\b" + prefix + r"_[0-9A-Fa-f]+\b", code):
            if name not in seen:
                if re.search(r"\b" + re.escape(name) +
                             r"\s*\[[^]\n]+\]\s*\(", code):
                    out.append(f"extern long long (*{name}[])();")
                elif re.search(r"\b" + re.escape(name) + r"\s*\(", code):
                    out.append(f"extern long long (*{name})();")
                elif re.search(r"\b" + re.escape(name) +
                               r"\.(?:chunk|chunk_limit|next_free|object_base|alignment_mask)\b", code):
                    out.append(f"extern struct obstack {name};")
                elif re.search(r"\b" + re.escape(name) +
                               r"\.(?:st_mode|st_dev|st_ino|st_blksize)\b", code):
                    out.append(f"extern struct stat {name};")
                elif (re.search(r"\b" + re.escape(name) + r"\s*(?:\+\+|--)", code) or
                      re.search(r"(?:\+\+|--)\s*" + re.escape(name) + r"\b", code)):
                    out.append(f"extern unsigned char *{name};")
                elif re.search(r"\b" + re.escape(name) + r"\.(?:c_cc|c_[io cl]flag)", code):
                    out.append(f"extern struct termios {name};")
                elif re.search(r"\b" + re.escape(name) + r"\.sa_(?:handler|flags|mask)", code):
                    out.append(f"extern struct sigaction {name};")
                elif name in aggregate_types:
                    out.append(f"extern struct {aggregate_types[name]} {name};")
                elif re.search(r"\b" + re.escape(name) + r"\.tv_(?:sec|nsec)", code):
                    out.append(f"extern struct timespec {name};")
                elif re.search(r"\b" + re.escape(name) + r"\.(?:start|end)\b", code):
                    out.append(f"extern struct re_registers {name};")
                elif re.search(r"\b" + re.escape(name) + r"\s*=", code):
                    out.append(f"extern long long {name};")
                else:
                    out.append(f"extern {ctype} {name}[];")
                seen.add(name)
    for name in re.findall(r"\boff_[0-9A-Fa-f]+\b", code):
        if name not in seen:
            if re.search(r"\b" + re.escape(name) +
                         r"\s*\[[^]\n]+\]\s*\(", code):
                out.append(f"extern long long (*{name}[])();")
            elif re.search(r"\b" + re.escape(name) + r"\s*\(", code):
                out.append(f"extern long long (*{name})();")
            elif re.search(r"\b" + re.escape(name) + r"\s*\[", code):
                out.append(f"extern char *{name}[];")
            else:
                out.append(f"extern char *{name};")
            seen.add(name)
    return out


def _scoped_global_decls(code: str, scoped: dict[str, str]) -> list[str]:
    """Keep IDA's leading C++ global-scope qualifier distinct from locals."""
    out = []
    local_arrays = set(re.findall(
        r"\b[A-Za-z_]\w*(?:\s+[A-Za-z_]\w*)*\s+(\w+)\s*\[[^]]+\]\s*;",
        code))
    for alias, original in scoped.items():
        label = original.replace('"', '')
        if re.search(r"\b" + re.escape(alias) + r"\s*\(", code):
            out.append(f'extern long long {alias}() __asm__("{label}");')
        elif re.search(r"\b" + re.escape(alias) +
                       r"\.(?:st_mode|st_dev|st_ino|st_blksize|st_atim|st_mtim)\b", code):
            out.append(f'extern struct stat {alias} __asm__("{label}");')
        elif re.search(r"\b" + re.escape(alias) +
                       r"\.tv_(?:sec|usec)\b", code):
            out.append(f'extern struct timeval {alias} __asm__("{label}");')
        elif re.search(r"\b" + re.escape(alias) + r"\s*\[", code):
            out.append(f'extern char *{alias} __asm__("{label}");')
        elif (re.search(r"\*\s*" + re.escape(alias) + r"\b", code) or
              re.search(r"\b" + re.escape(alias) +
                        r"\s*=\s*\([^)]*char\s*\*", code)):
            out.append(f'extern char *{alias} __asm__("{label}");')
        elif any(re.search(r"\b" + re.escape(alias) + r"\s*=\s*" +
                           re.escape(local) + r"\b", code)
                 for local in local_arrays):
            out.append(f'extern void *{alias} __asm__("{label}");')
        else:
            out.append(f'extern long long {alias} __asm__("{label}");')
    return out


def prepare(code: str, ctx) -> str:
    try:
        # IDA sometimes prints the internal name of an anonymous C++/DWARF
        # type in a cast.  It carries no extra width information here.
        code = re.sub(r"\b[A-Za-z_]\w*::\$[A-Za-z0-9_]+", "long long", code)
        scoped: dict[str, str] = {}
        def replace_global_scope(match):
            original = match.group(1)
            alias = "__ida_global_" + original
            scoped[alias] = original
            return alias
        code = re.sub(r"(?<![A-Za-z0-9_$])::([A-Za-z_]\w*)",
                      replace_global_scope, code)
        code = code.replace("::", "")
        anonymous_type = "_IDA_siginfo_word" if "->si_tid" in code else "long long"
        code = re.sub(r"\$\$[A-Za-z0-9_$]+", anonymous_type, code)
        # IDA occasionally applies const to a pointer and then emits stores
        # through it.  Removing the qualifier preserves those stores.
        code = re.sub(r"\bconst\s+([A-Za-z_]\w*(?:\s+\w+)?)\s*\*", r"\1 *", code)
        for scalar in re.findall(r"\blong long\s+(\w+)\s*;\s*//", code):
            code = re.sub(r"\b" + re.escape(scalar) + r"\.ru_isrss\b", scalar, code)
        # Transparent-union internals printed by IDA are merely alternate
        # views of the same scalar storage.
        code = re.sub(r"\b(\w+)\.(?:__[iu]ptr|__value)\b", r"\1", code)
        real_rusage = set(re.findall(
            r"\bstruct\s+rusage\s+\**\s*(\w+)", code))
        for base_name in set(re.findall(
                r"\b(\w+)(?:\[[^]\n]+\])?(?:\.|->)ru_(?:isrss|oublock)\b",
                code)) - real_rusage:
            code = re.sub(
                r"\b" + re.escape(base_name) + r"(\[[^]\n]+\])?\.ru_(?:isrss|oublock)\b",
                lambda m: base_name + (m.group(1) or ""), code)
            code = re.sub(
                r"\b" + re.escape(base_name) + r"->ru_(?:isrss|oublock)\b",
                "(*" + base_name + ")", code)
        code = re.sub(r"\b(\w+)\.__ru_isrss_word\b", r"\1", code)
        # Some optimized outputs retain FILE field names after losing the
        # pointer's FILE type.  The explicit cast restores that recovered use.
        code = re.sub(r"\b(\w+)->(_IO_(?:read|write|buf)_(?:ptr|end|base)|_flags)\b",
                      r"((FILE *)\1)->\2", code)
        # IDA's MSVC-style vector lane fields have a direct address-based C
        # equivalent and GCC vectors do not expose those field spellings.
        base = r"((?:\b\w+(?:\[[^]\n]+\])*|\(\*\w+\)\[[^]\n]+\]))"
        lanes = (("m128i_i64|m128i_u64|m128_u64", "long long"),
                 ("m128i_i32|m128i_u32", "int"),
                 ("m128i_i16|m128i_u16", "short"),
                 ("m128i_i8|m128i_u8|m128_i8|m128_u8", "signed char"))
        for fields, ctype in lanes:
            code = re.sub(base + r"\.(?:" + fields + r")\s*\[([^]]+)\]",
                          r"((" + ctype + r" *)&\1)[\2]", code)
            code = re.sub(base + r"->(?:" + fields + r")\s*\[([^]]+)\]",
                          r"((" + ctype + r" *)\1)[\2]", code)
            code = re.sub(base + r"\.(?:" + fields + r")\b",
                          r"((" + ctype + r" *)&\1)", code)
            code = re.sub(base + r"->(?:" + fields + r")\b",
                          r"((" + ctype + r" *)\1)", code)
        code = re.sub(r"\b(dword_[0-9A-Fa-f]+)\.si_tid\b", r"\1", code)
        code = re.sub(
            r"\b(xmmword_[0-9A-Fa-f]+)\.si_(signo|code)\b",
            lambda m: "((int *)&" + m.group(1) + ")[" +
                      ("0" if m.group(2) == "signo" else "2") + "]",
            code)
        code = re.sub(
            r"(_mm(?:256)?_[A-Za-z0-9_]+\([^;\n]+?\))\.m128i_i64\b",
            r"({ __m128i _dec_v = \1; (long long *)&_dec_v; })", code)
        code = re.sub(
            r"\(struct\s+(timespec|timeval)\)\s*"
            r"(_mm[A-Za-z0-9_]*\([^;\n]+\))",
            lambda m: "({ __m128i _dec_time = " + m.group(2) +
                      "; *(struct " + m.group(1) + " *)&_dec_time; })",
            code)
        # IDA prints rebased interior pointers as `new + old - base`; make
        # the byte-address arithmetic explicit so C does not first attempt
        # the invalid pointer-plus-pointer subexpression.
        ptr_atom = r"(?:\(char\s*\*\)\s*)?\*?\w+(?:\[[^]\n]+\])*"
        code = re.sub(
            r"(?P<a>\(char\s*\*\)\s*\*?\w+(?:\[[^]\n]+\])*)\s*\+\s*"
            r"(?P<b>" + ptr_atom + r")\s*-\s*"
            r"(?P<c>\(char\s*\*\)\s*\*?\w+(?:\[[^]\n]+\])*)",
            lambda m: "(char *)((unsigned long long)(" + m.group("a") +
                      ") + (unsigned long long)(" + m.group("b") +
                      ") - (unsigned long long)(" + m.group("c") + "))",
            code)
        code = re.sub(
            r"\(unsigned\s+long\s+long\)\s*\(\s*(qword_[0-9A-Fa-f]+)\s*-\s*"
            r"(unk_[0-9A-Fa-f]+)\s*\)",
            r"((unsigned long long)\1 - (unsigned long long)\2)", code)
        # GCC vectors require an aggregate spelling for the all-zero value
        # which IDA prints as a scalar literal.
        for vector_type, vector_name in re.findall(
                r"\b(__m(?:128|256)[id]?)\s+(\w+)\s*(?:[;=]|\[)", code):
            code = re.sub(
                r"\b" + re.escape(vector_name) + r"\s*=\s*0[uUlL]*\s*;",
                vector_name + " = (" + vector_type + "){0};", code)
        # `_OWORD` is IDA's integer view of the same 16 bytes.  Make vector
        # copies into recovered `_OWORD` arrays explicitly bit-preserving.
        for oword_name in re.findall(r"\b_OWORD\s+(\w+)\s*\[", code):
            code = re.sub(
                r"\b" + re.escape(oword_name) +
                r"(\[[^]\n]+\])\s*=\s*((?:_mm[A-Za-z0-9_]*\([^;\n]*\)|\w+))\s*;",
                lambda m: oword_name + m.group(1) + " = (_OWORD)(" +
                          m.group(2) + ");", code)
        for struct_type, pointer_name in re.findall(
                r"\bstruct\s+(\w+)\s*\*\s*(\w+)", code):
            code = re.sub(
                r"\*\s*" + re.escape(pointer_name) + r"\s*=\s*0\s*;",
                "*" + pointer_name + " = (struct " + struct_type + "){0};",
                code)
            code = re.sub(
                r"\b" + re.escape(pointer_name) +
                r"(\[[^]\n]+\])\s*=\s*0\s*;",
                pointer_name + r"\1 = (struct " + struct_type + "){0};",
                code)
        decls = (_known_decls(code, ctx.func_name) + _intrinsic_decls(code)
                 + _pointer_call_decls(code, ctx) + _sibling_decls(code, ctx)
                 + _assigned_callee_decls(code, ctx) + _ida_global_decls(code)
                 + _scoped_global_decls(code, scoped))
        return (_PRELUDE + "\n" + "\n".join(decls) +
                "\n\n/* decbench: target follows */\n" + code)
    except Exception:
        return _PRELUDE + "\n" + code


def _already_declared(source: str, name: str) -> bool:
    header = source.split("/* decbench: target follows */", 1)[0]
    return bool(re.search(
        r"^(?:extern|typedef)\b[^;\n]*\b" + re.escape(name) + r"\b[^;]*;",
        header, re.M))


def repair(source: str, stderr: str, ctx) -> str | None:
    """Add declarations requested by GCC while retaining IDA's body verbatim."""
    try:
        changed = False
        # Optimized recursive functions occasionally have a recovered formal
        # list which contradicts their own call sites.  An old-style pointer
        # cast retains the exact emitted arguments and the recovered result
        # ABI while disabling only that contradictory arity check.
        arity_names = set(re.findall(
            r"(?:too few|too many) arguments to function [‘']([^’']+)[’']",
            stderr))
        if ctx.func_name in arity_names:
            marker = "/* decbench: target follows */"
            before, sep, target_part = source.partition(marker)
            brace = target_part.find("{")
            if sep and brace >= 0:
                head, body = target_part[:brace + 1], target_part[brace + 1:]
                match = re.search(
                    r"^\s*(.*?)\b" + re.escape(ctx.func_name) + r"\s*\(",
                    head, re.S)
                if match:
                    result_type = match.group(1).strip()
                    result_type = re.sub(
                        r"\b(?:static|extern|inline|__fastcall|__cdecl)\b", "",
                        result_type).strip()
                    if result_type and "(" not in result_type and ")" not in result_type:
                        new_body = re.sub(
                            r"\b" + re.escape(ctx.func_name) + r"\s*\(",
                            "((" + result_type + " (*)())" + ctx.func_name + ")(",
                            body)
                        if new_body != body:
                            source = before + sep + head + new_body
                            changed = True

        subtraction_sites = re.findall(
            r":(\d+):(\d+): error: invalid operands to binary -", stderr)
        if subtraction_sites:
            lines = source.splitlines(keepends=True)
            atom = (r"(?:\([^()\n]+\)\s*)?(?:&\s*)?"
                    r"[A-Za-z_]\w*(?:\[[^]\n]+\])*")
            for line_text, column_text in subtraction_sites:
                line_index = int(line_text) - 1
                if not 0 <= line_index < len(lines):
                    continue
                line = lines[line_index]
                candidates = list(re.finditer(
                    r"(?P<a>" + atom + r")\s*-\s*(?P<b>" + atom + r")",
                    line))
                if not candidates:
                    continue
                column = int(column_text) - 1
                match = min(candidates,
                            key=lambda item: abs(item.start() - column))
                replacement = ("((char *)(" + match.group("a") +
                               ") - (char *)(" + match.group("b") + "))")
                lines[line_index] = (line[:match.start()] + replacement +
                                     line[match.end():])
                changed = True
            if changed:
                source = "".join(lines)

        and_sites = re.findall(
            r":(\d+):(\d+): error: invalid operands to binary &", stderr)
        if and_sites:
            lines = source.splitlines(keepends=True)
            atom = (r"(?:\([^()\n]+\)\s*)?(?:&\s*)?"
                    r"[A-Za-z_]\w*(?:\[[^]\n]+\])*")
            for line_text, column_text in and_sites:
                line_index = int(line_text) - 1
                if not 0 <= line_index < len(lines):
                    continue
                line = lines[line_index]
                candidates = list(re.finditer(
                    r"(?P<a>" + atom + r")\s*&\s*(?P<b>" + atom + r")",
                    line))
                if not candidates:
                    continue
                column = int(column_text) - 1
                match = min(candidates,
                            key=lambda item: abs(item.start() - column))
                replacement = ("((unsigned long long)(" + match.group("a") +
                               ") & (unsigned long long)(" +
                               match.group("b") + "))")
                lines[line_index] = (line[:match.start()] + replacement +
                                     line[match.end():])
                changed = True
            if changed:
                source = "".join(lines)

        declarations = []
        target = source.rsplit("/* decbench: target follows */", 1)[-1]
        target_syntax = re.sub(
            r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'', "", target)
        type_names = set(re.findall(r"unknown type name [‘']([^’']+)[’']", stderr))
        for name in sorted(type_names):
            if re.match(r"^[A-Za-z_]\w*$", name) and name not in _C_WORDS:
                declarations.append(f"typedef long long {name};")

        names = set(re.findall(
            r"error: [‘']([A-Za-z_]\w*)[’'] undeclared", stderr))
        for name in sorted(names):
            if name in type_names or _already_declared(source, name):
                continue
            # A parse error in a local declaration can make GCC subsequently
            # call that local "undeclared".  Do not turn such cascades into a
            # conflicting external object.
            if re.search(r"\b" + re.escape(name) + r"(?:\[[^;]*\])?\s*;\s*//", target):
                continue
            if name in {"stdin", "stdout", "stderr"}:
                declarations.append(f"extern FILE *{name};")
            elif re.search(r"\b" + re.escape(name) + r"\s*\(", target_syntax):
                declarations.append(f"extern long long {name}();")
            elif re.search(r"\b" + re.escape(name) + r"\s*\[", target):
                if re.search(r"\b" + re.escape(name) +
                             r"\s*\[[^]\n]+\]\s*\[", target):
                    declarations.append(f"extern unsigned char *{name}[];")
                elif re.search(r"\b" + re.escape(name) +
                             r"\s*\[[^]\n]+\]\s*\(", target):
                    declarations.append(f"extern long long (*{name}[])();")
                elif re.search(r"\b" + re.escape(name) + r"\s*=", target):
                    declarations.append(f"extern long long *{name};")
                else:
                    declarations.append(f"extern long long {name}[];")
            elif re.search(r"\b" + re.escape(name) +
                           r"\.(?:start|end)\b", target):
                declarations.append(f"extern struct re_registers {name};")
            elif re.search(r"\b" + re.escape(name) +
                           r"\.(?:__jmpbuf|__mask_was_saved|__saved_mask)\b", target):
                declarations.append(f"extern struct __jmp_buf_tag {name};")
            elif re.search(
                    r"\bsig(?:empty|fill|add|del|is)set\s*\(\s*&\s*" +
                    re.escape(name) + r"\b", target):
                declarations.append(f"extern sigset_t {name};")
            elif re.search(r"\b" + re.escape(name) +
                           r"\.(?:st_mode|st_dev|st_ino|st_blksize|st_size)\b", target):
                declarations.append(f"extern struct stat {name};")
            elif re.search(r"\b" + re.escape(name) +
                           r"\.(?:chunk|chunk_limit|next_free|object_base|alignment_mask)\b", target):
                declarations.append(f"extern struct obstack {name};")
            elif re.search(r"\b" + re.escape(name) + r"\.name\b", target):
                declarations.append(f"extern struct option {name};")
            elif re.search(r"(?:\*" + re.escape(name) + r"\b|\b" +
                           re.escape(name) + r"\s*->)", target):
                declarations.append(f"extern unsigned char *{name};")
            else:
                struct_type = None
                direct_type = None
                aggregate_assignment = re.search(
                    r"\b" + re.escape(name) +
                    r"\s*=\s*\(\{[^\n]*\bstruct\s+"
                    r"(timespec|timeval)\b[^\n]*", target)
                if aggregate_assignment:
                    struct_type = aggregate_assignment.group(1)
                direct_members = {
                    "__val": "sigset_t", "c_cc": "struct termios",
                    "c_iflag": "struct termios", "c_oflag": "struct termios",
                    "c_cflag": "struct termios", "c_lflag": "struct termios",
                    "_flags": "FILE", "_IO_read_ptr": "FILE",
                    "_IO_write_ptr": "FILE", "_IO_buf_base": "FILE",
                }
                member_types = {
                    "tv_sec": "timeval", "tv_usec": "timeval",
                    "st_mode": "stat", "st_uid": "stat", "st_gid": "stat",
                    "st_size": "stat", "st_atim": "stat", "st_mtim": "stat",
                    "st_dev": "stat", "st_ino": "stat",
                    "sa_handler": "sigaction", "sa_flags": "sigaction",
                    "sa_mask": "sigaction", "re_nsub": "re_pattern_buffer",
                    "buffer": "re_pattern_buffer",
                    "c_iflag": "termios", "c_oflag": "termios",
                    "c_cflag": "termios", "c_lflag": "termios",
                    "ru_isrss": "rusage", "ru_oublock": "rusage",
                }
                if struct_type:
                    field_match = None
                elif re.search(r"\b" + re.escape(name) + r"\.tv_nsec\b", target):
                    struct_type = "timespec"
                    field_match = None
                else:
                    field_match = re.search(
                        r"\b" + re.escape(name) + r"\.(\w+)", target)
                if field_match and not struct_type:
                    field = field_match.group(1)
                    direct_type = direct_members.get(field)
                    struct_type = member_types.get(field)
                for stype, local in re.findall(
                        r"\bstruct\s+(\w+)\s+(\w+)\s*;\s*//", target):
                    if re.search(r"\b" + re.escape(local) + r"\s*=\s*" +
                                 re.escape(name) + r"\b", target):
                        struct_type = stype
                        break
                if direct_type:
                    declarations.append(f"extern {direct_type} {name};")
                elif struct_type:
                    declarations.append(f"extern struct {struct_type} {name};")
                else:
                    declarations.append(f"extern long long {name};")

        if not declarations:
            return source if changed else None
        block = ("/* decbench: repair declarations */\n" +
                 "\n".join(declarations) + "\n")
        marker = "/* decbench: target follows */"
        if marker in source:
            return source.replace(marker, block + marker, 1)
        return block + source
    except Exception:
        return None
